SELECT
    COUNT(1) AS count,
    ROUND(SUM(NVL(ORIGINAL_FARE, NVL(TRX_AMOUNT, 0))) / 100, 2) AS totalPrice,
    ROUND(SUM(NVL(TOTAL_AMOUNT, 0)) / 100, 2) AS totalDebit,
    ROUND(SUM(GREATEST(NVL(ORIGINAL_FARE, NVL(TRX_AMOUNT, 0)) - NVL(TRX_AMOUNT, 0), 0)) / 100, 2) AS totalDiscount,
    ROUND(SUM(NVL(OVERTIME_AMOUNT, 0)) / 100, 2) AS totalOvertime
FROM GATE_TXN_PAY
WHERE 1 = 1

    AND THIRD_USER_ID = #{request.thirdUserId,jdbcType=VARCHAR}


