    AND TXN_DATE >= #{request.startDate,jdbcType=VARCHAR}


    AND TXN_DATE <= #{request.endDate,jdbcType=VARCHAR}

SELECT COUNT(1)
FROM GATE_TXN_PAY
WHERE THIRD_USER_ID = #{thirdUserId,jdbcType=VARCHAR}
  AND SIGN_CHANNEL_CODE = #{paymentVendor,jdbcType=VARCHAR}
  AND (DEBIT_STATUS IS NULL OR DEBIT_STATUS != 'SUCCESS')

  AND CREATE_TIME >= #{requestTime,jdbcType=TIMESTAMP}

SELECT
    NVL(SUM(CASE WHEN DEBIT_STATUS IN ('INIT', 'PROCESSING') THEN 1 ELSE 0 END), 0) AS UNPAID_COUNT,
    NVL(SUM(CASE WHEN DEBIT_STATUS IN ('FAIL', 'RETRY') THEN 1 ELSE 0 END), 0) AS FAILURE_COUNT
FROM GATE_TXN_PAY
WHERE THIRD_USER_ID = #{thirdUserId,jdbcType=VARCHAR}
  AND TXN_DATE >= #{startDate,jdbcType=VARCHAR}

SELECT *
FROM (
    SELECT 
    FROM GATE_TXN_PAY
    WHERE ORIGINAL_FARE IS NULL
      AND IN_STATION IS NOT NULL
      AND OUT_STATION IS NOT NULL
      AND TXN_DATE >= #{startDate,jdbcType=VARCHAR}
      AND TXN_DATE <= #{endDate,jdbcType=VARCHAR}
    ORDER BY TXN_DATE, ID
)
WHERE ROWNUM <= #{limit}

