SELECT *
FROM (
    SELECT 
    FROM GATE_TXN_PAY
    WHERE OFFLINE_FLAG = 'Y'
      AND DEBIT_STATUS = 'INIT'
      AND DISCOUNT_CALC_STATUS = 'OFFLINE_FARE_PENDING'
      AND TXN_DATE >= #{startDate,jdbcType=VARCHAR}
      AND TXN_DATE <= #{endDate,jdbcType=VARCHAR}
    ORDER BY TXN_DATE, ID
)
WHERE ROWNUM <= #{limit}

SELECT COUNT(1) AS txnCount,
       COUNT(DISTINCT CARD_ID) AS cardCount
FROM GATE_TXN_PAY
WHERE OFFLINE_FLAG = 'Y'
  AND TXN_DATE >= #{startDate,jdbcType=VARCHAR}
  AND TXN_DATE <= #{endDate,jdbcType=VARCHAR}
